if (!root) {
    root = new TreeNode<T>(item);
    return;
}
TreeNode<T>* curr = root;
TreeNode<T>* parent = nullptr;
while (curr) {
    parent = curr;
    if (item < curr->data) {
        curr = curr->left;
    } else {
        curr = curr->right;
    }
}
if (item < parent->data) {
    parent->left = new TreeNode<T>(item);
} else {
    parent->right = new TreeNode<T>(item);
}

